function Badge({value}:{value:string}){const color=/Hoàn tất|Sẵn sàng đăng|Đã chốt|Đã đăng|Đã giải quyết|Đang hợp tác/.test(value)?'green':/Chờ|Đang tư vấn|Cao/.test(value)?'orange':/Từ chối|Quá hạn|chuyển cấp|chỉnh sửa|Không thành công/.test(value)?'red':/sản xuất|triển khai|thương lượng/.test(value)?'purple':'gray';return <span className={'badge '+color}>{value}</span>}
function Avatar({name,color,square=false}:{name:string,color?:string,square?:boolean}){return <span className={'avatar '+(square?'square ':'')+(color?'':'orange')} style={color?{background:color+'22',color}:undefined}>{initials(name)}</span>}
